function highdpi_init(){if(jQuery(".replace-2x").css("font-size","1px")){var e=jQuery("img.replace-2x").get();for(var t=0;t<e.length;t++){var n=e[t].src;n=n.replace("images","images/hires");e[t].src=n}}}jQuery(document).ready(function(){highdpi_init()});$(function(){$("a[href*=\\#]:not([href=\\#])").click(function(){if(location.pathname.replace(/^\//,"")==this.pathname.replace(/^\//,"")||location.hostname==this.hostname){var e=$(this.hash);e=e.length?e:$("[name="+this.hash.slice(1)+"]");if(e.length){$("html,body").animate({scrollTop:e.offset().top},500);return false}}})});$(window).scroll(function(){if($(this).scrollTop()<204){$("#header_container").slideUp("fast")}else{$("#header_container").slideDown("fast")}})